-- Suitable Production Database Dump
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `brain_conversations`;
CREATE TABLE `brain_conversations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Nuevo Pensamiento',
  `provider` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'groq',
  `model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `brain_messages`;
CREATE TABLE `brain_messages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint unsigned NOT NULL,
  `role` enum('user','assistant','system') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'user',
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tokens_used` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `brain_messages_conversation_id_foreign` (`conversation_id`),
  CONSTRAINT `brain_messages_conversation_id_foreign` FOREIGN KEY (`conversation_id`) REFERENCES `brain_conversations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `campaigns`;
CREATE TABLE `campaigns` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `group_id` int DEFAULT NULL,
  `template_id` int NOT NULL DEFAULT '2',
  `preset_template` varchar(255) NOT NULL DEFAULT 'clasica',
  `subject` varchar(255) NOT NULL,
  `preheader` varchar(255) DEFAULT '',
  `hero_title` varchar(255) DEFAULT NULL,
  `hero_desc` text,
  `hero_image` varchar(255) NOT NULL DEFAULT 'hero-grupo-clinico.jpg',
  `pilar1_title` varchar(255) DEFAULT NULL,
  `pilar1_desc` text,
  `pilar2_title` varchar(255) DEFAULT NULL,
  `pilar2_desc` text,
  `pilar3_title` varchar(255) DEFAULT NULL,
  `pilar3_desc` text,
  `split_content` text,
  `gallery_json` text,
  `ai_provider` varchar(50) DEFAULT 'groq',
  `ai_prompt` text,
  `status` varchar(50) NOT NULL DEFAULT 'borrador',
  `sent_count` int DEFAULT '0',
  `total_count` int DEFAULT '0',
  `user_id` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `clients`;
CREATE TABLE `clients` (
  `id` int NOT NULL AUTO_INCREMENT,
  `empresa` varchar(255) NOT NULL,
  `contacto_nombre` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `telefono` varchar(100) DEFAULT '',
  `cargo` varchar(255) DEFAULT '',
  `region_comuna` varchar(255) DEFAULT 'Santiago, RM',
  `tamano_equipo` int DEFAULT '15',
  `estado` varchar(50) NOT NULL DEFAULT 'nuevo',
  `notas` text,
  `fecha_tallaje` date DEFAULT NULL,
  `monto_cotizacion` decimal(12,2) DEFAULT NULL,
  `ultimo_envio_tipo` varchar(100) DEFAULT NULL,
  `ultimo_envio_fecha` datetime DEFAULT NULL,
  `asignado_a` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_email` (`email`),
  KEY `idx_estado` (`estado`)
) ENGINE=InnoDB AUTO_INCREMENT=542 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `contact_groups`;
CREATE TABLE `contact_groups` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `description` text,
  `color` varchar(50) DEFAULT '#1E8888',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `email_logs`;
CREATE TABLE `email_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `client_id` int DEFAULT NULL,
  `campaign_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `template_id` int DEFAULT '1',
  `recipient_email` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'simulado',
  `details` text,
  `sent_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_recip` (`recipient_email`)
) ENGINE=InnoDB AUTO_INCREMENT=3241 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `group_members`;
CREATE TABLE `group_members` (
  `group_id` int NOT NULL,
  `client_id` int NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`group_id`,`client_id`),
  KEY `idx_client` (`client_id`),
  CONSTRAINT `fk_gm_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gm_group` FOREIGN KEY (`group_id`) REFERENCES `contact_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `order_items`;
CREATE TABLE `order_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL,
  `product_name` varchar(255) NOT NULL,
  `category` varchar(100) DEFAULT 'Top Clínico',
  `variation_color` varchar(100) DEFAULT 'Azul Marino',
  `variation_size` varchar(50) DEFAULT 'M',
  `quantity` int DEFAULT '1',
  `price` decimal(12,2) NOT NULL,
  `subtotal` decimal(12,2) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `wc_order_id` int DEFAULT NULL,
  `customer_name` varchar(255) NOT NULL,
  `customer_email` varchar(255) NOT NULL,
  `customer_city` varchar(100) DEFAULT 'Santiago',
  `total_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shipping_amount` decimal(12,2) DEFAULT '0.00',
  `status` varchar(50) NOT NULL DEFAULT 'completed',
  `payment_method` varchar(100) DEFAULT 'Transbank Webpay Plus',
  `items_count` int DEFAULT '1',
  `date_created` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `wc_order_id` (`wc_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `search_trends`;
CREATE TABLE `search_trends` (
  `id` int NOT NULL AUTO_INCREMENT,
  `keyword` varchar(255) NOT NULL,
  `search_volume` int NOT NULL,
  `growth_rate` decimal(6,2) NOT NULL,
  `category` varchar(100) DEFAULT 'General',
  `period_type` varchar(50) NOT NULL,
  `intent_level` varchar(100) DEFAULT 'Alta Intención de Compra',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `key` varchar(191) NOT NULL,
  `value` longtext,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `traffic_metrics`;
CREATE TABLE `traffic_metrics` (
  `id` int NOT NULL AUTO_INCREMENT,
  `period_type` varchar(50) NOT NULL,
  `period_date` date NOT NULL,
  `sessions` int DEFAULT '0',
  `visitors` int DEFAULT '0',
  `orders_count` int DEFAULT '0',
  `revenue` decimal(12,2) DEFAULT '0.00',
  `ad_spend` decimal(12,2) DEFAULT '0.00',
  `ctr` decimal(5,2) DEFAULT '0.00',
  `cpa` decimal(12,2) DEFAULT '0.00',
  `cvr` decimal(5,2) DEFAULT '0.00',
  `aov` decimal(12,2) DEFAULT '0.00',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `role` varchar(50) NOT NULL DEFAULT 'enviador',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS=1;
